% Lab 2 - Image Reading and Display
clc; clear; close all;

I = imread('peppers.png');      % RGB image
G = rgb2gray(I);                % convert to grayscale
E = histeq(G);                  % histogram equalization

figure('Name', 'Lab 2');
subplot(2, 2, 1); imshow(I); title('Original');
subplot(2, 2, 2); imshow(G); title('Grayscale');
subplot(2, 2, 3); imhist(G); title('Histogram');
subplot(2, 2, 4); imshow(E); title('Equalized');

fprintf('Image size: %d x %d\n', size(G, 1), size(G, 2));
